                nc = nc + 1; if (lo_f_crh !== dlo_f_crh[5]) begin bad = bad + 1; if (bad <= 5) $display("LP_MISMATCH port=f_crh cycle=%0d flat=%h landed=%h", cyc, dlo_f_crh[5], lo_f_crh); end
                nc = nc + 1; if (lo_f_bt !== dlo_f_bt[5]) begin bad = bad + 1; if (bad <= 5) $display("LP_MISMATCH port=f_bt cycle=%0d flat=%h landed=%h", cyc, dlo_f_bt[5], lo_f_bt); end
            end
        end
        if (bad == 0 && nc > 0) $display("LP_LOCKSTEP PASS MUT=%0d compared=%0d cycles=6000 warm=37", MUT, nc);
        else $display("LP_LOCKSTEP FAIL MUT=%0d mismatches=%0d of %0d", MUT, bad, nc);
        $finish;
    end
endmodule
